-- Jo's standard answers for AI email replies (Jo 29 Oct 2026, AI answers list, Q6). Server (service role) only.
CREATE TABLE IF NOT EXISTS public.ai_reply_answers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  topic text NOT NULL,
  answer text NOT NULL,
  active boolean NOT NULL DEFAULT true,
  sort int NOT NULL DEFAULT 0,
  updated_at timestamptz DEFAULT now(),
  updated_by uuid NULL
);
REVOKE ALL ON public.ai_reply_answers FROM anon, authenticated;
GRANT ALL ON public.ai_reply_answers TO service_role;
ALTER TABLE public.ai_reply_answers ENABLE ROW LEVEL SECURITY;
-- No policies: browsers and signed-in users can never read or write the answers.
-- BEGIN seed (generated by scripts/ai-reply-answers-seed-sql.ts from AI_SEED_ANSWERS — do not edit by hand)
-- Jo's starting answers, only into an empty table.
INSERT INTO public.ai_reply_answers (topic, answer, active, sort)
SELECT v.topic, v.answer, true, v.sort FROM (VALUES
  ('Ceilings only', 'We only do ceiling insulation (no underfloor or walls).', 1),
  ('Batts, not blow-in', 'Our quotes are for R5.0 batts, not blow-in insulation, so no holes are cut in the ceiling.', 2),
  ('R6.0/R7.0', 'R6.0 and R7.0 are available. If they ask about R6.0 or R7.0, give the revised price and rebate for their ceiling size, worked out from the job facts at $33/m² for R6.0 and $35/m² for R7.0, and tell them to tell the installer they want it at the free Ready Check. The rebate is the same as for R5.0 (it depends only on ceiling size and location); never make up a different rebate.', 3),
  ('Old insulation removal', 'Old insulation is removed only where needed, at $15/m²; the installer checks how much at the Ready Check.', 4),
  ('Extras', 'Extras like cleaning the roof cavity: the installer can quote them at the Ready Check.', 5),
  ('Free Ready Check', 'The free Ready Check: a certified installer comes to the home, measures the ceilings, checks the existing insulation and confirms the job, then the owner gets their final quote. They see the exact price before agreeing to anything.', 6),
  ('Existing insulation and the rebate', 'The rebate needs any existing insulation to be below R2.0, and it has to be checked at the Ready Check — age alone isn''t enough. Owners never need to go into the roof or send photos.', 7),
  ('Order spots are released', 'Spots are released in the order they were saved, so we can''t give install dates before that. When it''s their turn an installer texts and emails a few times for the Ready Check.', 8),
  ('Steps after the quote', 'After they accept the quote, a licensed electrician does the electrical safety check (PIESA) before any insulation goes in, then the installer puts the insulation in. We look after all the paperwork and the rebate.', 9),
  ('What the price includes', 'The price includes: the free Ready Check; R5.0 batts supplied and installed by a certified installer; the electrician''s electrical safety check (PIESA) ($349); our Accredited Person fee for the paperwork and rebate claim ($349). Electrical upgrades aren''t included — if needed they get a separate quote first.', 10),
  ('Own electrician for electrical upgrades', 'An owner''s own electrician can do the electrical upgrades if they show a REC (Registered Electrical Contractor) licence and $5 million public liability insurance, which we approve. They must sign up with us as an electrician first. They do the work and get the certificate of electrical safety (COES) and our forms back to us before the 30 days run out; otherwise a new electrical safety check (PIESA) is needed ($349). All forms go through our system so the rebate can be claimed. Sign-up link: https://portal.homeinsulationvictoria.com.au/electrician-onboarding', 11),
  ('Payment plan', 'We don''t offer a payment plan. Say so with empathy: we pay the installer, the electrician and the products as each step happens. The payments are already spread: $349 for the electrical safety check (PIESA), 10% to book the install, and the rest on install day. Their spot stays saved.', 12),
  ('Low income / concession', 'Be very warm. Say sorry it''s hard. The rebate is the same for every home and is the biggest help we can give. There is no extra discount and they don''t need to send a concession card. Their spot stays saved and there is no pressure.', 13),
  ('Cheaper quote / scam / too expensive', 'Explain the value and why other quotes can be cheaper. What our price covers: an electrical safety check (PIESA) for wiring and downlight fire risk; CII-certified installers and REC electricians, with their licences and $5 million insurance checked; an approved product that meets the Australian standard; and our Accredited Person handles the evidence and claims the rebate upfront for them. Cheaper quotes often skip the PIESA, use uncertified workers, or can''t give the rebate. They''re welcome to compare, with no obligation. Never name the program; "Accredited Person" is fine.', 14),
  ('Existing electrical certificate', 'An existing electrical certificate can''t be used. Under the government''s rebate rules the electrical safety check (PIESA) must be done by an electrician working under a REC, whose $5 million insurance we approve, within 30 days of the install.', 15),
  ('Garage / flat roof / cathedral ceiling / no manhole', 'We can''t do garages, flat roofs, cathedral ceilings or homes with no manhole. Say so kindly.', 16),
  ('Underfloor / walls', 'We only do ceilings. For underfloor, the installer can quote it directly at the free Ready Check, outside our system.', 17),
  ('Cancel / not going ahead', 'If they say they''re cancelling or not going ahead, reply with a short, kind note. Only if the job facts show the job is closed or cancelled, say we''ve closed it and they can reply if they change their mind. Otherwise thank them kindly and say we''ve got their message and will take care of it, without promising it''s closed. A plain "thanks" still needs no reply.', 18),
  ('Rental / landlord', 'Rentals qualify. It''s the same steps and the same rebate.', 19),
  ('Paying by card', 'They can pay by card for the $349 electrical safety check (PIESA) and the 10% deposit. The balance is by bank transfer or PayID.', 20),
  ('Home on install day', 'No one needs to be home on install day if the crew can get in. It takes about 4 hours.', 21),
  ('Other languages', 'If they write in another language, reply in simple English.', 22),
  ('Tenant', 'If a tenant writes, we''re happy to help, but the owner needs to give permission.', 23),
  ('Installer access', 'The batts go in through the manhole. No roof access is needed.', 24),
  ('Wording', 'In every reply, the first time you mention it, write "electrical safety check (PIESA)". Anything that is required is "the government''s rebate rules", never "our rule". Say "electrical upgrades", never "fixes". Say "rebate" and never use scheme words.', 25)
) AS v(topic, answer, sort)
WHERE NOT EXISTS (SELECT 1 FROM public.ai_reply_answers);
-- END seed
